import { spawn } from "node:child_process";
import { WebSocket } from "ws";
const port = 3197;
const server = spawn(process.execPath, ["server.mjs"], { env: { ...process.env, GAME_PORT: String(port) }, stdio: "ignore" });
const wait = ms => new Promise(r => setTimeout(r, ms));
async function until(fn, timeout = 5000) { const start = Date.now(); while (Date.now() - start < timeout) { const v = fn(); if (v) return v; await wait(25); } throw new Error("Timed out waiting for server event"); }
function connect() { return new Promise((resolve, reject) => { const ws = new WebSocket(`ws://127.0.0.1:${port}`); ws.once("open", () => resolve(ws)); ws.once("error", reject); }); }
function listen(ws) { const messages = []; ws.on("message", b => messages.push(JSON.parse(b))); return messages; }
try {
 await until(async () => { try { return (await fetch(`http://127.0.0.1:${port}/health`)).ok; } catch { return false; } });
 const a = await connect(), am = listen(a), b = await connect(), bm = listen(b);
 a.send(JSON.stringify({ type: "matchmake", mode: "1v1" })); await until(() => am.find(m => m.type === "joined"));
 b.send(JSON.stringify({ type: "matchmake", mode: "1v1" })); await until(() => am.find(m => m.type === "match_start") && bm.find(m => m.type === "match_start"));
 const ar = am.find(m => m.type === "joined"), br = bm.find(m => m.type === "joined");
 a.send(JSON.stringify({ type: "state", x: 0, z: 0, facing: 1, stamina: 100, action: "punch" }));
 b.send(JSON.stringify({ type: "state", x: 1, z: 0, facing: -1, stamina: 100, action: "idle" }));
 await wait(3050); a.send(JSON.stringify({ type: "attack", kind: "punch" }));
 await until(() => am.find(m => m.type === "hit") || bm.find(m => m.type === "hit"));
 console.log("matchmaking, match start, state relay, and authoritative hit: PASS");
 a.close(); b.close(); await wait(100);
 const c = await connect(), cm = listen(c), d = await connect(), dm = listen(d);
 c.send(JSON.stringify({ type: "create_room", mode: "1v1" })); await until(() => cm.find(m => m.type === "room_created"));
 const code = cm.find(m => m.type === "room_created").roomCode;
 d.send(JSON.stringify({ type: "join_room", roomCode: code })); await until(() => dm.find(m => m.type === "joined"));
 console.log("private room create/join: PASS"); c.close(); d.close();
} finally { server.kill("SIGTERM"); }
'

